{
	public static void main(String args[]) throws Exception
	{
		BufferedReader f=new BufferedReader(new InputStreamReader(System.in));
		// BufferedReader f=new BufferedReader(new FileReader("Text_Document_Analysis.in"));
		f.readLine();
		String temp=f.readLine();
		String[] arr1=temp.split("\\([a-zA-Z_]*\\)");
		int one=0;
		for(int x=0;x<arr1.length;x++)
		{
			String[] temparr=arr1[x].split("_+");
			for(int y=0;y<temparr.length;y++)
				one=Math.max(one,temparr[y].length());
		}
		int pos=0;
		int two=0;
		boolean flag=false;
		boolean flag1=false;
		for(int x=0;x<temp.length();x++)
		{
			if(temp.charAt(x)=='(')
				flag=true;
			if(temp.charAt(x)==')')
			{
				flag1=false;
				flag=false;
			}
			if(flag&&temp.substring(x,x+1).matches("[a-zA-Z]"))
			{
				if(flag1) continue;
				two++;
				flag1=true;
			}
			if(temp.substring(x,x+1).matches("_"))
				flag1=false;
		}
		System.out.println(one+" "+two);
	}
}
